select case when o.status in ('SHIPPED', 'RETURNED') then 'tier_1' else 'other' end as status_group, o.channel, count(oi.unit_price) as unit_price_count, count(oi.quantity) as quantity_count from order_items oi join products p on oi.product_id = p.id join orders o on o.id = oi.order_id where o.store_id = 21 group by case when o.status in ('SHIPPED', 'RETURNED') then 'tier_1' else 'other' end, o.channel order by unit_price_count desc;
